package com.sitionix.forgeai.application.agentproxy;
import com.sitionix.forgeai.domain.model.agentproxy.*; import com.sitionix.forgeai.domain.port.ForgeAgentClient; import com.sitionix.forgeai.domain.usecase.ManageAgentProjectAssets; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AgentProjectAssetsUseCase implements ManageAgentProjectAssets { private final ForgeAgentClient client; public List<AgentProjectAsset> list(UUID p){return client.listProjectAssets(p);} public AgentProjectAsset create(UUID p,CreateAgentProjectAssetCommand c){return client.createProjectAsset(p,c);} public AgentProjectAsset get(UUID p,UUID a){return client.getProjectAsset(p,a);} public AgentAssetMetrics metrics(UUID p,UUID a){return client.getProjectAssetMetrics(p,a);} public AgentAssetCapabilities capabilities(UUID p,UUID a){return client.getProjectAssetCapabilities(p,a);} public List<AgentLogSource> monitoring(UUID p,UUID a){return client.listProjectAssetMonitoring(p,a);} public AgentLogSource monitor(UUID p,UUID a,SaveAgentAssetMonitoringCommand c){return client.createProjectAssetMonitoring(p,a,c);} public void delete(UUID p,UUID a){client.deleteProjectAsset(p,a);} }
